import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { motion } from 'framer-motion';
import { Mail, Lock, LogIn, Package } from 'lucide-react';
import toast from 'react-hot-toast';
import ValidatedInput from '../../components/forms/ValidatedInput';

const loginSchema = z.object({
    email: z.string()
        .min(1, 'Email is required')
        .email('Please enter a valid email address'),
    password: z.string()
        .min(1, 'Password is required')
});

const LoginPage = () => {
    const { login } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const [isLoading, setIsLoading] = useState(false);

    const { register, handleSubmit, formState: { errors } } = useForm({
        resolver: zodResolver(loginSchema)
    });

    const getDefaultRoute = (role) => {
        switch (role) {
            case 'admin':
                return '/admin/dashboard';
            case 'sales_rep':
                return '/sales-rep/dashboard';
            case 'dispatch_partner':
                return '/dispatch/dashboard';
            default:
                return '/login';
        }
    };

    const onSubmit = async (data) => {
        setIsLoading(true);
        try {
            const result = await login(data.email, data.password);

            toast.success(`Welcome back, ${result.user.firstName}!`);

            // Route based on role
            const route = getDefaultRoute(result.user.role);
            navigate(route, { replace: true });
        } catch (error) {
            const message = error.response?.data?.message || 'Login failed. Please try again.';
            toast.error(message);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-indigo-50 via-white to-teal-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-4">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
                className="w-full max-w-md"
            >
                <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-8">
                    {/* Logo/Brand */}
                    <div className="text-center mb-8">
                        <motion.div
                            initial={{ scale: 0 }}
                            animate={{ scale: 1 }}
                            transition={{ delay: 0.2, type: 'spring', stiffness: 200 }}
                            className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-indigo-100 dark:bg-indigo-900/30 mb-4"
                        >
                            <Package className="w-8 h-8 text-indigo-600 dark:text-indigo-400" />
                        </motion.div>
                        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                            Inventory Sales Pro
                        </h1>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Sign in to your account
                        </p>
                    </div>

                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
                        <ValidatedInput
                            label="Email Address"
                            name="email"
                            type="email"
                            icon={Mail}
                            autoComplete="email"
                            error={errors.email?.message}
                            {...register('email')}
                        />

                        <ValidatedInput
                            label="Password"
                            name="password"
                            type="password"
                            icon={Lock}
                            autoComplete="current-password"
                            error={errors.password?.message}
                            {...register('password')}
                        />

                        <motion.button
                            type="submit"
                            disabled={isLoading}
                            whileHover={{ scale: 1.01 }}
                            whileTap={{ scale: 0.99 }}
                            className="w-full flex items-center justify-center gap-2 px-4 py-3 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white font-medium transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                        >
                            {isLoading ? (
                                <>
                                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    Signing in...
                                </>
                            ) : (
                                <>
                                    <LogIn className="w-5 h-5" />
                                    Sign In
                                </>
                            )}
                        </motion.button>
                    </form>

                    {/* Test Credentials */}
                    {/* <div className="mt-6 p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                        <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-2">
                            Test Credentials (Password: Password@123)
                        </p>
                        <div className="space-y-1 text-xs text-gray-600 dark:text-gray-400">
                            <p>Admin: admin@salespro.com</p>
                            <p>Sales Rep: john.smith@salespro.com</p>
                            <p>Dispatch: dispatch1@speedexlogistics.com</p>
                        </div>
                    </div> */}
                </div>
            </motion.div>
        </div>
    );
};

export default LoginPage;
